import React, { useState, useEffect } from "react";

function RecipeGenerator() {
  const [darkMode, setDarkMode] = useState(false);
  const [mode, setMode] = useState("ingredients"); // "ingredients" or "name"
  const [recipeName, setRecipeName] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState([]); // Should now hold structured recipe objects
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Update the document's class for dark mode
    if (darkMode) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [darkMode]);

  // Helper function to clean text (still useful for final display cleanup)
  const cleanText = (text) => {
    // Check if text is valid string before replacing
    if (typeof text === 'string') {
      return text.replace(/\*/g, "").trim();
    }
    return text; // Return as is if not a string
  };

  // Simplified submit function - expects structured JSON from backend
  const handleApiResponse = (data) => {
    console.log("Received structured data from backend:", data);
    if (data.error) {
      throw new Error(data.error);
    }
    if (data.recipe && typeof data.recipe === 'object') {
      // Ensure the received recipe is a single object, wrap in array for state
      const recipeObject = data.recipe;

      // Apply cleanText to all relevant fields *after* receiving structured data
      const cleanedRecipe = {
        title: cleanText(recipeObject.title) || "Untitled Recipe", // Provide fallback title
        ingredients: Array.isArray(recipeObject.ingredients)
          ? recipeObject.ingredients.map(cleanText)
          : [],
        equipment: Array.isArray(recipeObject.equipment)
          ? recipeObject.equipment.map(cleanText)
          : [],
        instructions: Array.isArray(recipeObject.instructions)
          ? recipeObject.instructions.map(cleanText)
          : [], // Expecting array now
        tips: Array.isArray(recipeObject.tips)
          ? recipeObject.tips.map(cleanText)
          : [],
      };

      setRecipes([cleanedRecipe]); // Store the single, cleaned recipe object in the array
      setError(null);
    } else {
      console.warn("Received unexpected data format or empty recipe:", data);
      // Handle cases where backend might return raw text on parse failure, or empty recipe
      if(typeof data.recipe === 'string'){
         setError("Backend sent unformatted recipe text. Parsing failed.");
         setRecipes([]); // Clear recipes
      } else {
         setRecipes([]); // Clear recipes if format is wrong or recipe is missing
         setError(null); // Or set a specific message like "No recipe found"
      }

    }
  };

  const handleSubmitByName = async () => {
    if (!recipeName) {
      setError("Please enter a recipe name.");
      return;
    }
    setLoading(true);
    setError(null); // Clear previous errors
    setRecipes([]); // Clear previous recipes
    try {
      const response = await fetch(
        "http://localhost:5000/api/generate-by-name", // Ensure your backend URL is correct
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ recipeName }),
        }
      );
      if (!response.ok) {
         // Try to get error message from backend response body
        const errorData = await response.json().catch(() => ({})); // Catch potential JSON parse error
        throw new Error(`HTTP error! status: ${response.status} - ${errorData.error || response.statusText}`);
      }
      const data = await response.json();
      handleApiResponse(data); // Use the common handler
    } catch (err) {
      console.error("Error generating recipe by name:", err);
      setError(`Failed to generate recipe by name: ${err.message}`);
      setRecipes([]); // Clear recipes on error
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitByIngredients = async () => {
    if (!ingredients) {
      setError("Please enter ingredients.");
      return;
    }
    setLoading(true);
    setError(null); // Clear previous errors
    setRecipes([]); // Clear previous recipes
    try {
      const response = await fetch(
        "http://localhost:5000/api/generate", // Ensure your backend URL is correct
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ingredients,
            mealType,
            cuisine,
            cookingTime,
            complexity,
          }),
        }
      );
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(`HTTP error! status: ${response.status} - ${errorData.error || response.statusText}`);
      }
      const data = await response.json();
      handleApiResponse(data); // Use the common handler
    } catch (err) {
      console.error("Error generating recipe by ingredients:", err);
      setError(`Failed to generate recipe by ingredients: ${err.message}`);
      setRecipes([]); // Clear recipes on error
    } finally {
      setLoading(false);
    }
  };

  // Main submit handler chooses which specific handler to call
  const handleSubmit = () => {
    if (mode === "name") {
      handleSubmitByName();
    } else {
      handleSubmitByIngredients();
    }
  };

  return (
    <div
      className={`min-h-screen bg-gradient-to-b ${
        darkMode ? "from-gray-900 to-gray-800" : "from-white to-gray-100"
      } flex items-center justify-center p-4 transition-colors duration-300 overflow-hidden text-gray-800 dark:text-white`}
    >
      {/* Dark Mode Toggle */}
      <div className="absolute top-4 right-4 flex space-x-2">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
          aria-label={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl h-[calc(100vh-2rem)]">

        {/* MIDDLE - Recipe Generator Panel */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-lg p-6 flex flex-col h-full overflow-y-auto"> {/* Added shadow-lg and overflow-y-auto */}
          <h2 className="text-2xl font-bold text-center mb-6"> {/* Increased font size */}
            Recipe Generator
          </h2>

          {/* Mode Switch */}
          <div className="mb-6 flex justify-center">
            <label className="flex items-center space-x-2 cursor-pointer">
              <span className="text-gray-800 dark:text-white">
                By Ingredients
              </span>
              <input
                type="checkbox"
                checked={mode === "name"}
                onChange={() =>
                  setMode(mode === "ingredients" ? "name" : "ingredients")
                }
                className="toggle-checkbox"
                aria-label="Switch between generating by ingredients or by name"
              />
              <span className="toggle-switch"></span>
              <span className="text-gray-800 dark:text-white">By Name</span>
            </label>
            {/* Toggle switch styles */}
            <style>{`
              .toggle-checkbox { display: none; }
              .toggle-switch { width: 40px; height: 20px; background-color: #ccc; border-radius: 10px; position: relative; cursor: pointer; transition: background-color 0.3s; }
              .toggle-checkbox:checked + .toggle-switch { background-color: #4b9af4; }
              .toggle-switch::after { content: ''; width: 16px; height: 16px; background-color: white; border-radius: 50%; position: absolute; top: 2px; left: 2px; transition: transform 0.3s; }
              .toggle-checkbox:checked + .toggle-switch::after { transform: translateX(20px); }
            `}</style>
          </div>

          {/* Conditional Fields */}
          <div className="flex-grow space-y-4"> {/* Reduced space-y-6 to space-y-4 */}
            {mode === "ingredients" ? (
              <>
                {/* Group 1 */}
                <div>
                  <label
                    className="block font-semibold mb-1"
                    htmlFor="ingredients"
                  >
                    Ingredients*
                  </label>
                  <input
                    id="ingredients"
                    type="text"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="e.g. tomato, potato, onion"
                    value={ingredients}
                    onChange={(e) => setIngredients(e.target.value)}
                    required // Mark as required
                  />
                </div>
                <div>
                  <label className="block font-semibold mb-1" htmlFor="mealType">
                    Meal Type
                  </label>
                  <select
                    id="mealType"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    value={mealType}
                    onChange={(e) => setMealType(e.target.value)}
                  >
                    <option>Breakfast</option>
                    <option>Lunch</option>
                    <option>Dinner</option>
                    <option>Snack</option>
                    <option>Dessert</option> {/* Added Dessert */}
                  </select>
                </div>
                {/* Group 2 */}
                <div>
                  <label className="block font-semibold mb-1" htmlFor="cuisine">
                    Cuisine Preference
                  </label>
                  <input
                    id="cuisine"
                    type="text"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="e.g. Indian, Italian (optional)"
                    value={cuisine}
                    onChange={(e) => setCuisine(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block font-semibold mb-1" htmlFor="cookingTime">
                    Cooking Time
                  </label>
                  <select
                    id="cookingTime"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    value={cookingTime}
                    onChange={(e) => setCookingTime(e.target.value)}
                  >
                    <option>Less than 30 minutes</option>
                    <option>30-60 minutes</option>
                    <option>More than 1 hour</option>
                  </select>
                </div>
                 {/* Group 3 */}
                <div>
                  <label className="block font-semibold mb-1" htmlFor="complexity">
                    Complexity
                  </label>
                  <select
                    id="complexity"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    value={complexity}
                    onChange={(e) => setComplexity(e.target.value)}
                  >
                    <option>Beginner</option>
                    <option>Intermediate</option>
                    <option>Advanced</option>
                  </select>
                </div>
              </>
            ) : ( // Mode === "name"
              <div>
                <label
                  className="block font-semibold mb-1"
                  htmlFor="recipeName"
                >
                  Recipe Name*
                </label>
                <input
                  id="recipeName"
                  type="text"
                  className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="e.g. Classic Margherita Pizza"
                  value={recipeName}
                  onChange={(e) => setRecipeName(e.target.value)}
                  required // Mark as required
                />
              </div>
            )}
          </div> {/* End conditional fields */}

          {/* Submit Button */}
          <button
            onClick={handleSubmit}
            disabled={loading} // Disable button when loading
            className={`bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-4 rounded w-full mt-6 transition duration-150 ease-in-out ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {loading ? 'Generating...' : 'Generate Recipe'} {/* Show loading text */}
          </button>
        </div> {/* End Recipe Generator Panel */}


        {/* RIGHT - Recipe Output Panel */}
        {/* Added shadow-lg */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-lg p-6 flex flex-col h-full">
          <h2 className="text-2xl font-bold mb-4 text-center text-gray-800 dark:text-white"> {/* Increased font size */}
            Recipe Details
          </h2>

          {/* Scrollable area for recipe content */}
          <div className="flex-grow overflow-y-auto pr-2"> {/* Added padding-right for scrollbar */}
            {/* Error Display */}
            {error && (
              <p className="text-red-500 dark:text-red-400 text-center mb-4 font-semibold break-words"> {/* Added font-semibold & break-words */}
                Error: {error}
              </p>
            )}

            {/* Loading Spinner */}
            {loading && (
              <div className="flex items-center justify-center h-full">
                <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-500"></div> {/* Improved spinner */}
              </div>
            )}

            {/* Placeholder message */}
            {!loading && recipes.length === 0 && !error && (
              <p className="text-gray-500 dark:text-gray-400 text-center h-full flex items-center justify-center"> {/* Dark mode text lighter */}
                Your generated recipe will appear here.
              </p>
            )}

            {/* Recipe Display */}
            {!loading && recipes.length > 0 && (
              <div className="space-y-6">
                {recipes.map((recipe, index) => (
                  <div
                    key={index}
                    // Removed inner card styling, rendering directly
                    className="text-gray-800 dark:text-gray-200" // Base text colors
                  >
                    {/* Title */}
                    {recipe.title && (
                      <h3 className="text-xl font-bold text-center mb-5 underline decoration-blue-500 decoration-2 underline-offset-4"> {/* Increased font, margin, underline */}
                        {recipe.title}
                      </h3>
                    )}

                    {/* Ingredients Section */}
                    {recipe.ingredients && recipe.ingredients.length > 0 && (
                      <div className="mb-5"> {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2"> {/* Removed text-center, bold */}
                          Ingredients:
                        </h4>
                        <ul className="list-disc list-inside space-y-1 text-sm pl-2"> {/* Switched to ul/disc, added padding */}
                          {recipe.ingredients.map((ing, i) => (
                            <li key={i}>{ing}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {/* Equipment Section */}
                    {recipe.equipment && recipe.equipment.length > 0 && (
                      <div className="mb-5"> {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2"> {/* Removed text-center, bold */}
                          Equipment:
                        </h4>
                        <ul className="list-disc list-inside space-y-1 text-sm pl-2"> {/* ul/disc, added padding */}
                          {recipe.equipment.map((eq, i) => (
                            <li key={i}>{eq}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {/* Instructions Section - Renders Array */}
                    {recipe.instructions && recipe.instructions.length > 0 && (
                      <div className="mb-5"> {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2"> {/* Removed text-center, bold */}
                          Instructions:
                        </h4>
                        {/* Render instructions as an ordered list */}
                        <ol className="list-decimal list-outside space-y-2 text-sm pl-6 leading-relaxed"> {/* list-outside, added padding, line height */}
                          {recipe.instructions.map((step, i) => (
                            <li key={i}>{step}</li>
                          ))}
                        </ol>
                      </div>
                    )}

                    {/* Tips Section */}
                    {recipe.tips && recipe.tips.length > 0 && (
                       <div className="mb-5"> {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2"> {/* Removed text-center, bold */}
                          Optional Tips & Variations:
                        </h4>
                         <ul className="list-disc list-inside space-y-1 text-sm pl-2"> {/* ul/disc, added padding */}
                          {recipe.tips.map((tip, i) => (
                            <li key={i}>{tip}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div> // End individual recipe render
                ))}
              </div> // End recipes map container
            )}
          </div> {/* End Scrollable Area */}
        </div> {/* End Recipe Output Panel */}

      </div> {/* End Main Content Grid */}
    </div> // End Page Container
  );
}

export default RecipeGenerator;
